# =============================================================================
# Helper functions
# =============================================================================

.q4_get <- function(name, envir) {
  if (!exists(name, envir = envir, inherits = FALSE)) return(NULL)
  get(name, envir = envir, inherits = FALSE)
}

.q4_assignment_rhs <- function(expressions, target) {
  ans <- NULL

  for (expr in as.list(expressions)) {
    if (
      is.call(expr) &&
      length(expr) >= 3L &&
      as.character(expr[[1L]]) %in% c("<-", "=") &&
      is.symbol(expr[[2L]]) &&
      identical(as.character(expr[[2L]]), target)
    ) {
      ans <- expr[[3L]]
    }
  }

  ans
}

.q4_code <- function(expr) {
  if (is.null(expr)) return("")
  paste(deparse(expr, width.cutoff = 500L), collapse = " ")
}

.q4_has_call <- function(code_text, fun) {
  pattern <- paste0(
    "(^|[^[:alnum:]_.])(?:[[:alnum:]_.]+::)?\\Q",
    fun,
    "\\E\\s*\\("
  )

  isTRUE(grepl(pattern, code_text, perl = TRUE))
}

.q4_path_equal <- function(x, y) {
  if (
    !is.character(x) || length(x) != 1L || is.na(x) ||
    !is.character(y) || length(y) != 1L || is.na(y)
  ) {
    return(FALSE)
  }

  normalizePath(x, winslash = "/", mustWork = FALSE) ==
    normalizePath(y, winslash = "/", mustWork = FALSE)
}

.q4_data_shape_ok <- function(x, nr = 12L, nc = 6L) {
  is.data.frame(x) &&
    nrow(x) == nr &&
    ncol(x) == nc
}

.q4_names_ok <- function(x) {
  identical(
    as.character(x),
    c(
      "session_id",
      "activity",
      "location",
      "duration_min",
      "steps",
      "water_l"
    )
  )
}

.q4_named_numeric_equal <- function(x, expected, tolerance = 1e-8) {
  if (!is.numeric(x) || length(x) != length(expected)) return(FALSE)

  if (!identical(names(x), names(expected))) return(FALSE)

  isTRUE(
    all.equal(
      as.numeric(x),
      as.numeric(expected),
      tolerance = tolerance,
      check.attributes = FALSE
    )
  )
}

.q4_count_table_ok <- function(x) {
  if (!is.data.frame(x)) return(FALSE)

  if (!all(c("activity", "n") %in% names(x))) return(FALSE)

  observed <- x[, c("activity", "n"), drop = FALSE]
  observed$activity <- as.character(observed$activity)

  expected <- data.frame(
    activity = c("Cycle", "Run", "Strength", "Yoga"),
    n = c(2L, 3L, 4L, 3L),
    stringsAsFactors = FALSE
  )

  observed <- observed[order(observed$activity), , drop = FALSE]
  expected <- expected[order(expected$activity), , drop = FALSE]

  row.names(observed) <- NULL
  row.names(expected) <- NULL

  identical(observed$activity, expected$activity) &&
    identical(as.integer(observed$n), expected$n)
}

.q4_count_sorted <- function(x) {
  if (!is.data.frame(x) || !"n" %in% names(x)) return(FALSE)
  all(diff(as.numeric(x$n)) <= 0)
}

.q4_add <- function(points, ok) {
  if (isTRUE(ok)) as.integer(points) else 0L
}

.q4_print_item <- function(ok, points, success_text, miss_text) {
  mark <- if (isTRUE(ok)) "[OK]" else "[--]"
  earned <- if (isTRUE(ok)) points else 0L

  cat(
    sprintf(
      "   %-4s %2d/%2d  %s\n",
      mark,
      earned,
      points,
      if (isTRUE(ok)) success_text else miss_text
    )
  )
}

# =============================================================================
# Main grader
# =============================================================================

grade_this <- function(file = "mastery_quiz_04.R") {

  grading_root <- normalizePath(
    getwd(),
    winslash = "/",
    mustWork = TRUE
  )

  on.exit(
    try(setwd(grading_root), silent = TRUE),
    add = TRUE
  )

  cat("\n")
  cat("STT303 Mastery Quiz 4 - Lecture 6\n")
  cat("Problem-by-problem partial-credit grader\n")
  cat(strrep("=", 70), "\n", sep = "")

  if (!file.exists(file)) {
    cat("[FILE NOT FOUND] Could not find ", file, "\n", sep = "")
    cat("Keep mastery_quiz_04.R beside grade_this.R in the quiz project.\n")

    return(
      invisible(
        list(
          score = 0L,
          max_score = 100L,
          results = NULL
        )
      )
    )
  }

  required_packages <- c(
    "here",
    "readr",
    "dplyr",
    "skimr",
    "readxl"
  )

  missing_packages <- required_packages[
    !vapply(
      required_packages,
      requireNamespace,
      quietly = TRUE,
      FUN.VALUE = logical(1)
    )
  ]

  if (length(missing_packages) > 0L) {
    cat(
      "[SETUP NEEDED] Missing package(s): ",
      paste(missing_packages, collapse = ", "),
      "\n",
      sep = ""
    )
    cat("Install the missing packages, then run grade_this() again.\n")

    return(
      invisible(
        list(
          score = 0L,
          max_score = 100L,
          results = NULL
        )
      )
    )
  }

  parsed <- tryCatch(
    parse(file = file, keep.source = FALSE),
    error = function(e) e
  )

  if (inherits(parsed, "error")) {
    cat("[PARSE ERROR] R could not read the submission as valid R code.\n")
    cat("R message: ", conditionMessage(parsed), "\n", sep = "")
    cat(
      "Check quotation marks, commas, parentheses, and incomplete expressions.\n"
    )

    return(
      invisible(
        list(
          score = 0L,
          max_score = 100L,
          results = NULL
        )
      )
    )
  }

  # A clean helper environment supplies the Lecture 6 functions.
  # This prevents one omitted library() call from making every later problem
  # impossible to inspect.
  helper_env <- new.env(parent = baseenv())

  helper_env$read_csv <- readr::read_csv
  helper_env$read_excel <- readxl::read_excel
  helper_env$excel_sheets <- readxl::excel_sheets
  helper_env$glimpse <- dplyr::glimpse
  helper_env$count <- dplyr::count
  helper_env$skim <- skimr::skim
  helper_env$here <- here::here

  quiz_env <- new.env(parent = helper_env)

  execution_errors <- character()

  invisible(
    capture.output(
      for (i in seq_along(parsed)) {

        tryCatch(
          eval(parsed[[i]], envir = quiz_env),
          error = function(e) {
            execution_errors <<- c(
              execution_errors,
              paste0(
                "Expression ",
                i,
                ": ",
                conditionMessage(e)
              )
            )
            NULL
          }
        )

        # Restore the grading directory if student code changed it.
        try(setwd(grading_root), silent = TRUE)
      }
    )
  )

  getv <- function(name) .q4_get(name, quiz_env)

  code <- function(name) {
    .q4_code(
      .q4_assignment_rhs(
        parsed,
        name
      )
    )
  }

  full_code <- paste(
    vapply(
      as.list(parsed),
      .q4_code,
      character(1)
    ),
    collapse = "\n"
  )

  expected_csv <- here::here(
    "data",
    "fitness_checkins.csv"
  )

  expected_excel <- here::here(
    "data",
    "fitness_checkins.xlsx"
  )

  expected_names <- c(
    "session_id",
    "activity",
    "location",
    "duration_min",
    "steps",
    "water_l"
  )

  expected_missing <- c(
    session_id = 0,
    activity = 0,
    location = 0,
    duration_min = 2,
    steps = 0,
    water_l = 2
  )

  checkin_file <- getv("checkin_file")
  file_found <- getv("file_found")
  checkins <- getv("checkins")

  checkin_names <- getv("checkin_names")
  checkin_dim <- getv("checkin_dim")
  n_checkins <- getv("n_checkins")
  n_variables <- getv("n_variables")

  total_missing <- getv("total_missing")
  missing_by_variable <- getv("missing_by_variable")

  activity_counts <- getv("activity_counts")
  skim_result <- getv("skim_result")

  excel_file <- getv("excel_file")
  sheet_names <- getv("sheet_names")
  checkins_excel <- getv("checkins_excel")
  excel_dim <- getv("excel_dim")

  # =============================================================================
  # Problem 1
  # =============================================================================

  p1_path_value <- .q4_path_equal(
    checkin_file,
    expected_csv
  )

  p1_path_method <-
    .q4_has_call(code("checkin_file"), "here") &&
    grepl("\"data\"", code("checkin_file"), fixed = TRUE) &&
    grepl("\"fitness_checkins.csv\"", code("checkin_file"), fixed = TRUE)

  p1_found_value <-
    is.logical(file_found) &&
    length(file_found) == 1L &&
    isTRUE(file_found)

  p1_found_method <-
    .q4_has_call(code("file_found"), "file.exists") &&
    grepl("checkin_file", code("file_found"), fixed = TRUE)

  p1_import_shape <- .q4_data_shape_ok(checkins)

  p1_import_names <-
    is.data.frame(checkins) &&
    .q4_names_ok(names(checkins))

  p1_read_csv <- .q4_has_call(
    code("checkins"),
    "read_csv"
  )

  p1_score <-
    .q4_add(3, p1_path_value) +
    .q4_add(2, p1_path_method) +
    .q4_add(2, p1_found_value) +
    .q4_add(1, p1_found_method) +
    .q4_add(5, p1_import_shape) +
    .q4_add(3, p1_import_names) +
    .q4_add(4, p1_read_csv)

  cat("\nPROBLEM 1 - Locate and import the CSV file\n")
  .q4_print_item(
    p1_path_value, 3,
    "checkin_file points to the supplied CSV.",
    "checkin_file does not point to the supplied CSV. Check the project root, data folder, and filename."
  )
  .q4_print_item(
    p1_path_method, 2,
    "The path uses here() with the requested components.",
    "I did not detect here() with separate \"data\" and \"fitness_checkins.csv\" components."
  )
  .q4_print_item(
    p1_found_value, 2,
    "file_found is TRUE.",
    "file_found is not TRUE. First verify that checkin_file points to the included file."
  )
  .q4_print_item(
    p1_found_method, 1,
    "file.exists(checkin_file) is used.",
    "Use file.exists() on checkin_file rather than typing TRUE directly."
  )
  .q4_print_item(
    p1_import_shape, 5,
    "checkins has the expected 12 rows and 6 columns.",
    "checkins does not have the expected dimensions. Check that the supplied CSV was imported into checkins."
  )
  .q4_print_item(
    p1_import_names, 3,
    "The imported variable names match the file.",
    "The variables in checkins do not match the supplied CSV. Make sure you imported the correct file."
  )
  .q4_print_item(
    p1_read_csv, 4,
    "read_csv() is used for the import.",
    "I did not detect read_csv() in the assignment to checkins."
  )
  cat(sprintf("Problem 1 subtotal: %d/20\n", p1_score))

  # =============================================================================
  # Problem 2
  # =============================================================================

  p2_names_value <-
    is.character(checkin_names) &&
    identical(as.character(checkin_names), expected_names)

  p2_names_method <-
    .q4_has_call(code("checkin_names"), "names") &&
    grepl("checkins", code("checkin_names"), fixed = TRUE)

  p2_dim_value <-
    is.numeric(checkin_dim) &&
    length(checkin_dim) == 2L &&
    identical(as.integer(checkin_dim), c(12L, 6L))

  p2_dim_method <-
    .q4_has_call(code("checkin_dim"), "dim") &&
    grepl("checkins", code("checkin_dim"), fixed = TRUE)

  p2_nrow_value <-
    is.numeric(n_checkins) &&
    length(n_checkins) == 1L &&
    identical(as.integer(n_checkins), 12L)

  p2_nrow_method <- .q4_has_call(
    code("n_checkins"),
    "nrow"
  )

  p2_ncol_value <-
    is.numeric(n_variables) &&
    length(n_variables) == 1L &&
    identical(as.integer(n_variables), 6L)

  p2_ncol_method <- .q4_has_call(
    code("n_variables"),
    "ncol"
  )

  p2_score <-
    .q4_add(3, p2_names_value) +
    .q4_add(1, p2_names_method) +
    .q4_add(3, p2_dim_value) +
    .q4_add(1, p2_dim_method) +
    .q4_add(2, p2_nrow_value) +
    .q4_add(1, p2_nrow_method) +
    .q4_add(3, p2_ncol_value) +
    .q4_add(1, p2_ncol_method)

  cat("\nPROBLEM 2 - Inspect names and dimensions\n")
  .q4_print_item(
    p2_names_value, 3,
    "checkin_names contains the expected variable names.",
    "checkin_names is not the variable-name vector from checkins."
  )
  .q4_print_item(
    p2_names_method, 1,
    "names(checkins) is used.",
    "Use names() on checkins to inspect variable names."
  )
  .q4_print_item(
    p2_dim_value, 3,
    "checkin_dim has the correct dimensions.",
    "checkin_dim is not the expected two-number result. Remember: rows first, columns second."
  )
  .q4_print_item(
    p2_dim_method, 1,
    "dim(checkins) is used.",
    "Use dim() on checkins."
  )
  .q4_print_item(
    p2_nrow_value, 2,
    "n_checkins has the correct number of cases.",
    "n_checkins is not the number of rows in checkins."
  )
  .q4_print_item(
    p2_nrow_method, 1,
    "nrow() is used.",
    "Use nrow(checkins) for the number of cases."
  )
  .q4_print_item(
    p2_ncol_value, 3,
    "n_variables has the correct number of variables.",
    "n_variables is not the number of columns in checkins."
  )
  .q4_print_item(
    p2_ncol_method, 1,
    "ncol() is used.",
    "Use ncol(checkins) for the number of variables."
  )
  cat(sprintf("Problem 2 subtotal: %d/15\n", p2_score))

  # =============================================================================
  # Problem 3
  # =============================================================================

  glimpse_present <- grepl(
    "(^|[^[:alnum:]_.])(?:dplyr::)?glimpse\\s*\\(",
    full_code,
    perl = TRUE
  )

  glimpse_checkins <- grepl(
    "(?:dplyr::)?glimpse\\s*\\(\\s*checkins\\s*\\)",
    full_code,
    perl = TRUE
  )

  p3_score <-
    .q4_add(4, glimpse_present) +
    .q4_add(6, glimpse_checkins)

  cat("\nPROBLEM 3 - Inspect column types with glimpse()\n")
  .q4_print_item(
    glimpse_present, 4,
    "A glimpse() call is present.",
    "I did not detect glimpse(). Lecture 6 uses it for a compact view of names, inferred types, and example values."
  )
  .q4_print_item(
    glimpse_checkins, 6,
    "glimpse() is applied directly to checkins.",
    "A glimpse() call may be present, but it is not applied directly to checkins."
  )
  cat(sprintf("Problem 3 subtotal: %d/10\n", p3_score))

  # =============================================================================
  # Problem 4
  # =============================================================================

  p4_total_value <-
    is.numeric(total_missing) &&
    length(total_missing) == 1L &&
    identical(as.integer(total_missing), 4L)

  p4_total_sum <- .q4_has_call(
    code("total_missing"),
    "sum"
  )

  p4_total_isna <- .q4_has_call(
    code("total_missing"),
    "is.na"
  )

  p4_column_value <- .q4_named_numeric_equal(
    missing_by_variable,
    expected_missing
  )

  p4_colsums <- .q4_has_call(
    code("missing_by_variable"),
    "colSums"
  )

  p4_column_isna <- .q4_has_call(
    code("missing_by_variable"),
    "is.na"
  )

  p4_score <-
    .q4_add(5, p4_total_value) +
    .q4_add(1, p4_total_sum) +
    .q4_add(1, p4_total_isna) +
    .q4_add(5, p4_column_value) +
    .q4_add(2, p4_colsums) +
    .q4_add(1, p4_column_isna)

  cat("\nPROBLEM 4 - Check missing values\n")
  .q4_print_item(
    p4_total_value, 5,
    "total_missing correctly counts all missing cells.",
    "total_missing is not the total number of missing cells in checkins."
  )
  .q4_print_item(
    p4_total_sum, 1,
    "sum() is used.",
    "Use sum() to count the TRUE values produced by is.na()."
  )
  .q4_print_item(
    p4_total_isna, 1,
    "is.na() is used.",
    "Use is.na(checkins) to ask whether each cell is missing."
  )
  .q4_print_item(
    p4_column_value, 5,
    "missing_by_variable has the correct count for each variable.",
    "missing_by_variable does not match the missingness pattern in the supplied data."
  )
  .q4_print_item(
    p4_colsums, 2,
    "colSums() is used.",
    "Use colSums() to obtain one missing-value count per variable."
  )
  .q4_print_item(
    p4_column_isna, 1,
    "is.na() is used before colSums().",
    "Apply is.na() before colSums()."
  )
  cat(sprintf("Problem 4 subtotal: %d/15\n", p4_score))

  # =============================================================================
  # Problem 5
  # =============================================================================

  p5_value <- .q4_count_table_ok(
    activity_counts
  )

  p5_sorted <- .q4_count_sorted(
    activity_counts
  )

  p5_count_call <- .q4_has_call(
    code("activity_counts"),
    "count"
  )

  p5_activity <- grepl(
    "activity",
    code("activity_counts"),
    fixed = TRUE
  )

  p5_sort_code <- grepl(
    "sort\\s*=\\s*TRUE",
    code("activity_counts"),
    perl = TRUE
  )

  p5_score <-
    .q4_add(7, p5_value) +
    .q4_add(3, p5_count_call) +
    .q4_add(2, p5_activity) +
    .q4_add(1, p5_sorted) +
    .q4_add(2, p5_sort_code)

  cat("\nPROBLEM 5 - Count a categorical variable\n")
  .q4_print_item(
    p5_value, 7,
    "activity_counts contains the correct frequencies.",
    "activity_counts does not contain the correct counts for the activity categories."
  )
  .q4_print_item(
    p5_count_call, 3,
    "count() is used.",
    "Use dplyr::count() for this categorical-frequency check."
  )
  .q4_print_item(
    p5_activity, 2,
    "The activity variable is counted.",
    "The count should summarize activity, not another variable."
  )
  .q4_print_item(
    p5_sorted, 1,
    "The result is ordered from most to least frequent.",
    "The resulting n column is not ordered from most to least frequent."
  )
  .q4_print_item(
    p5_sort_code, 2,
    "sort = TRUE is supplied.",
    "Add sort = TRUE to count() as requested."
  )
  cat(sprintf("Problem 5 subtotal: %d/15\n", p5_score))

  # =============================================================================
  # Problem 6
  # =============================================================================

  p6_value <-
    is.data.frame(skim_result) &&
    nrow(skim_result) > 0L

  p6_skim <- .q4_has_call(
    code("skim_result"),
    "skim"
  )

  p6_input <- grepl(
    "checkins",
    code("skim_result"),
    fixed = TRUE
  )

  p6_score <-
    .q4_add(6, p6_value) +
    .q4_add(2, p6_skim) +
    .q4_add(2, p6_input)

  cat("\nPROBLEM 6 - Create a broad summary with skim()\n")
  .q4_print_item(
    p6_value, 6,
    "skim_result contains a structured skim summary.",
    "skim_result does not appear to contain the object returned by skim()."
  )
  .q4_print_item(
    p6_skim, 2,
    "skim() is used.",
    "Use skimr::skim()."
  )
  .q4_print_item(
    p6_input, 2,
    "skim() is applied to checkins.",
    "Apply skim() to the imported checkins dataset."
  )
  cat(sprintf("Problem 6 subtotal: %d/10\n", p6_score))

  # =============================================================================
  # Problem 7
  # =============================================================================

  p7_path_value <- .q4_path_equal(
    excel_file,
    expected_excel
  )

  p7_path_method <- .q4_has_call(
    code("excel_file"),
    "here"
  )

  p7_sheets_value <-
    is.character(sheet_names) &&
    identical(
      as.character(sheet_names),
      c("checkins", "notes")
    )

  p7_sheets_method <- .q4_has_call(
    code("sheet_names"),
    "excel_sheets"
  )

  p7_import_shape <- .q4_data_shape_ok(
    checkins_excel
  )

  p7_read_excel <- .q4_has_call(
    code("checkins_excel"),
    "read_excel"
  )

  p7_sheet_specified <- grepl(
    "sheet\\s*=\\s*[\"']checkins[\"']",
    code("checkins_excel"),
    perl = TRUE
  )

  p7_dim_value <-
    is.numeric(excel_dim) &&
    length(excel_dim) == 2L &&
    identical(as.integer(excel_dim), c(12L, 6L))

  p7_score <-
    .q4_add(2, p7_path_value) +
    .q4_add(1, p7_path_method) +
    .q4_add(3, p7_sheets_value) +
    .q4_add(1, p7_sheets_method) +
    .q4_add(3, p7_import_shape) +
    .q4_add(2, p7_read_excel) +
    .q4_add(1, p7_sheet_specified) +
    .q4_add(2, p7_dim_value)

  cat("\nPROBLEM 7 - Inspect the Excel workbook\n")
  .q4_print_item(
    p7_path_value, 2,
    "excel_file points to the supplied workbook.",
    "excel_file does not point to data/fitness_checkins.xlsx."
  )
  .q4_print_item(
    p7_path_method, 1,
    "here() is used to build the workbook path.",
    "Build excel_file from the project root with here()."
  )
  .q4_print_item(
    p7_sheets_value, 3,
    "sheet_names correctly identifies the workbook sheets.",
    "sheet_names does not match the supplied workbook. Use excel_sheets() to inspect it."
  )
  .q4_print_item(
    p7_sheets_method, 1,
    "excel_sheets() is used.",
    "Use readxl::excel_sheets(excel_file)."
  )
  .q4_print_item(
    p7_import_shape, 3,
    "checkins_excel has the expected dimensions.",
    "checkins_excel does not have the expected dimensions. Check which sheet was imported."
  )
  .q4_print_item(
    p7_read_excel, 2,
    "read_excel() is used.",
    "Use readxl::read_excel() for the Excel import."
  )
  .q4_print_item(
    p7_sheet_specified, 1,
    'The "checkins" sheet is explicitly selected.',
    'Specify sheet = "checkins".'
  )
  .q4_print_item(
    p7_dim_value, 2,
    "excel_dim correctly records the Excel data dimensions.",
    "excel_dim does not match dim(checkins_excel)."
  )
  cat(sprintf("Problem 7 subtotal: %d/15\n", p7_score))

  # =============================================================================
  # Final score
  # =============================================================================

  scores <- c(
    Problem_1 = p1_score,
    Problem_2 = p2_score,
    Problem_3 = p3_score,
    Problem_4 = p4_score,
    Problem_5 = p5_score,
    Problem_6 = p6_score,
    Problem_7 = p7_score
  )

  max_scores <- c(
    Problem_1 = 20L,
    Problem_2 = 15L,
    Problem_3 = 10L,
    Problem_4 = 15L,
    Problem_5 = 15L,
    Problem_6 = 10L,
    Problem_7 = 15L
  )

  total <- sum(scores)

  if (length(execution_errors) > 0L) {
    cat("\nEXECUTION NOTES\n")
    cat(
      "The script produced ",
      length(execution_errors),
      " R error(s). The grader continued so later independent work could ",
      "still receive credit.\n",
      sep = ""
    )

    for (msg in head(execution_errors, 4L)) {
      cat("   - ", msg, "\n", sep = "")
    }

    if (length(execution_errors) > 4L) {
      cat(
        "   - ... ",
        length(execution_errors) - 4L,
        " additional error(s)\n",
        sep = ""
      )
    }
  }

  cat("\n")
  cat(strrep("=", 70), "\n", sep = "")
  cat("FINAL SCORE: ", total, "/100\n", sep = "")
  cat(strrep("-", 70), "\n", sep = "")

  for (nm in names(scores)) {
    cat(
      sprintf(
        "%-10s %2d/%2d\n",
        nm,
        scores[[nm]],
        max_scores[[nm]]
      )
    )
  }

  if (total == 100L) {
    cat("\nAll available points earned.\n")
  } else {
    cat(
      "\nReview the [--] lines above. They identify the specific component ",
      "to check for each problem.\n"
    )
  }

  results <- lapply(
    seq_along(scores),
    function(i) {
      list(
        problem = i,
        earned_points = as.integer(scores[[i]]),
        points = as.integer(max_scores[[i]]),
        pass = identical(
          as.integer(scores[[i]]),
          as.integer(max_scores[[i]])
        )
      )
    }
  )

  invisible(
    list(
      score = as.integer(total),
      max_score = 100L,
      passed = identical(as.integer(total), 100L),
      results = results,
      execution_errors = execution_errors
    )
  )
}
